1	"use client";
2	import Image from "@/components/AppImage";
3	import { CSSProperties, ReactNode, useState, useEffect, useRef } from "react";
4	
5	type TriggerMode = "hover" | "click" | "pageload";
6	
7	interface TooltipProps {
8	  label?: string;
9	  content: ReactNode;
10	  showArrow?: boolean;
11	  showQuestionMark?: boolean;
12	  triggerMode?: TriggerMode;
13	  className?: string;
14	  style?: CSSProperties;
15	  children?: ReactNode;
16	  childrenClassName?: string;
17	}
18	
19	const TOOLTIP_EVENT = "GLOBAL_TOOLTIP_EVENT";
20	let isAnyClickTooltipOpen = false;
21	
22	export default function Tooltip({
23	  label,
24	  content,
25	  showArrow = true,
26	  showQuestionMark = true,
27	  triggerMode = "hover",
28	  className,
29	  style,
30	  children,
31	  childrenClassName,
32	}: TooltipProps) {
33	  const [isVisible, setIsVisible] = useState(triggerMode === "pageload");
34	  const hideTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
35	  const containerRef = useRef<HTMLDivElement>(null);
36	  const tooltipIdRef = useRef(Math.random().toString(36).substring(2, 9));
37	
38	  const isClickMode = triggerMode === "click";
39	
40	  // pageload: auto-dismiss after 3s
41	  useEffect(() => {
42	    if (triggerMode !== "pageload") return;
43	    const timer = setTimeout(() => setIsVisible(false), 3000);
44	    return () => clearTimeout(timer);
45	  }, [triggerMode]);
46	
47	  // click / pageload: dismiss on click outside
48	  useEffect(() => {
49	    if (triggerMode === "hover" || !isVisible) return;
50	    const handleOutside = (e: MouseEvent) => {
51	      if (
52	        containerRef.current &&
53	        !containerRef.current.contains(e.target as Node)
54	      ) {
55	        handleClose();
56	      }
57	    };
58	    document.addEventListener("mousedown", handleOutside);
59	    return () => document.removeEventListener("mousedown", handleOutside);
60	  }, [isVisible, triggerMode]);
61	
62	  useEffect(() => {
63	    return () => {
64	      if (hideTimerRef.current) clearTimeout(hideTimerRef.current);
65	    };
66	  }, []);
67	
68	  useEffect(() => {
69	    const handleTooltipAction = (e: Event) => {
70	      const customEvent = e as CustomEvent<{
71	        activeId: string;
72	        mode: TriggerMode;
73	        action: "open" | "close";
74	      }>;
75	      const { activeId, mode, action } = customEvent.detail;
76	
77	      if (activeId === tooltipIdRef.current) return;
78	
79	      if (action === "open") {
80	        if (mode === "click") {
81	          // 新開 Click Tooltip 時，關閉其他 hover / pageload tooltip
82	          clearHideTimer();
83	          setIsVisible(false);
84	        } else if (mode === "hover") {
85	          // 新開 Hover Tooltip 時，關閉其他 hover / pageload tooltip
86	          if (triggerMode === "hover") {
87	            clearHideTimer();
88	            setIsVisible(false);
89	          }
90	        }
91	      }
92	    };
93	
94	    window.addEventListener(TOOLTIP_EVENT, handleTooltipAction);
95	    return () => {
96	      window.removeEventListener(TOOLTIP_EVENT, handleTooltipAction);
97	    };
98	  }, [triggerMode]);
99	
100	  const clearHideTimer = () => {
101	    if (hideTimerRef.current) {
102	      clearTimeout(hideTimerRef.current);
103	      hideTimerRef.current = null;
104	    }
105	  };
106	
107	  const scheduleHide = () => {
108	    clearHideTimer();
109	    hideTimerRef.current = setTimeout(() => setIsVisible(false), 1500);
110	  };
111	
112	  const handleOpen = () => {
113	    // 如果目前有 Click Tooltip 開著，且現在觸發的是 Hover，直接攔截不顯示
114	    if (isAnyClickTooltipOpen && triggerMode === "hover") return;
115	
116	    clearHideTimer();
117	    setIsVisible(true);
118	
119	    if (isClickMode) {
120	      isAnyClickTooltipOpen = true;
121	    }
122	
123	    dispatchGlobalEvent("open");
124	  };
125	
126	  const handleClose = () => {
127	    clearHideTimer();
128	    setIsVisible(false);
129	
130	    if (isClickMode) {
131	      isAnyClickTooltipOpen = false;
132	      dispatchGlobalEvent("close");
133	    }
134	  };
135	
136	  const dispatchGlobalEvent = (action: "open" | "close") => {
137	    const event = new CustomEvent(TOOLTIP_EVENT, {
138	      detail: {
139	        activeId: tooltipIdRef.current,
140	        mode: triggerMode,
141	        action: action,
142	      },
143	    });
144	    window.dispatchEvent(event);
145	  };
146	
147	  const hoverProps =
148	    triggerMode === "hover"
149	      ? {
150	          onMouseEnter: handleOpen,
151	          onMouseLeave: scheduleHide,
152	        }
153	      : {};
154	
155	  const clickProps = isClickMode
156	    ? {
157	        onClick: () => {
158	          if (!isVisible) {
159	            handleOpen();
160	          } else {
161	            handleClose();
162	          }
163	        },
164	      }
165	    : {};
166	
167	  return (
168	    <div
169	      ref={containerRef}
170	      className={`relative inline-flex shrink-0 items-center ${className ?? ""}`}
171	      style={style}
172	    >
173	      {label || showQuestionMark ? (
174	        <button
175	          type="button"
176	          className={`inline-flex items-center gap-1 cursor-pointer p-1.5 hover:bg-gray-90/10 ${
177	            label ? "rounded-md" : "rounded-full"
178	          } ${isVisible && isClickMode ? "bg-gray-90/10" : ""}`}
179	          {...hoverProps}
180	          {...clickProps}
181	        >
182	          {showQuestionMark && (
183	            <Image
184	              src="/icon/function/icon_circle-help.svg"
185	              alt="Info"
186	              width={16}
187	              height={16}
188	            />
189	          )}
190	          {label && <span className="text-[14px] text-gray-90">{label}</span>}
191	        </button>
192	      ) : (
193	        <div
194	          className={`inline-flex items-center cursor-pointer ${childrenClassName ?? ""}`}
195	          {...hoverProps}
196	          {...clickProps}
197	        >
198	          {children}
199	        </div>
200	      )}
201	
202	      {isVisible && (
203	        <div
204	          role="tooltip"
205	          className={`absolute top-full mt-2 left-1/2 -translate-x-1/2 z-30 pointer-events-auto whitespace-nowrap bg-gray-90 text-white body-1-reg px-[12px] py-[4px] rounded-[8px]`}
206	          {...hoverProps}
207	        >
208	          {showArrow && (
209	            <div className="absolute bottom-full left-1/2 -translate-x-1/2 border-[6px] border-transparent border-b-gray-90" />
210	          )}
211	          {isClickMode && (
212	            <button
213	              type="button"
214	              className="absolute top-0 right-1 p-3 text-white/60 hover:text-white leading-none cursor-pointer flex items-center justify-center text-[14px]"
215	              onClick={handleClose}
216	            >
217	              ✕
218	            </button>
219	          )}
220	          {content}
221	        </div>
222	      )}
223	    </div>
224	  );
225	}
